    "properties": {
	   "name": {
	     "type": "keyword"
	   },
      "age": {
        "type": "integer"
      },
      "created_at": {
        "type": "date"
      }
    }
  }
}
```

</details>

<details>
<summary>**2. 데이터 삽입**</summary>

