    ```java
    package com.example.userservice.util;

    import io.jsonwebtoken.Claims;
    import io.jsonwebtoken.JwtException;
    import io.jsonwebtoken.Jwts;
    import io.jsonwebtoken.security.Keys;
    import java.nio.charset.StandardCharsets;
    import java.util.Date;
    import javax.crypto.SecretKey;
    import org.springframework.beans.factory.annotation.Value;
    import org.springframework.stereotype.Component;

    @Component
    public class JwtUtil {

        private final SecretKey key;
        private final long accessTokenValidityInMs;
        private final long refreshTokenValidityInMs;

        public JwtUtil(
                @Value("${jwt.secret}") String secret,
                @Value("${jwt.access-token-validity-in-seconds}") long accessTokenValidityInSeconds,
                @Value("${jwt.refresh-token-validity-in-seconds}") long refreshTokenValidityInSeconds) {
            this.key = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
            this.accessTokenValidityInMs = accessTokenValidityInSeconds * 1000;
            this.refreshTokenValidityInMs = refreshTokenValidityInSeconds * 1000;
        }

        public String generateAccessToken(String email, Long userId) {
            return Jwts.builder()
                    .subject(email)
                    .claim("userId", userId)
                    .issuedAt(new Date())
                    .expiration(new Date(System.currentTimeMillis() + accessTokenValidityInMs))
                    .signWith(key)
                    .compact();
        }

        public String generateRefreshToken(String email, Long userId) {
            return Jwts.builder()
                    .subject(email)
                    .claim("userId", userId)
                    .issuedAt(new Date())
                    .expiration(new Date(System.currentTimeMillis() + refreshTokenValidityInMs))
                    .signWith(key)
                    .compact();
        }

        public boolean validateToken(String token) {
            try {
                Jwts.parser().verifyWith(key).build().parseSignedClaims(token);
                return true;
            } catch (JwtException | IllegalArgumentException e) {
                return false;
            }
        }

        public Claims getClaims(String token) {
            return Jwts.parser()
                    .verifyWith(key)
                    .build()
                    .parseSignedClaims(token)
                    .getPayload();
        }

        public String getEmailFromToken(String token) {
            return getClaims(token).getSubject();
        }

        public Long getUserIdFromToken(String token) {
            return getClaims(token).get("userId", Long.class);
        }
    }
    ```

