                reservation.updateStatus("APPROVED");
            } else if ("CANCELED".equals(status)) {
                if ("EXPIRED".equals(reservation.getStatus())) {
                    throw new IllegalArgumentException("EXPIRED 상태인 예약은 취소할 수 없습니다.");
