> 
> 
> public class Proxy implements java.io.Serializable {
>     @java.io.Serial
>     private static final long serialVersionUID = -2222568056686623797L;
>     
> 			. . .
>     
> 	  @CallerSensitive
>     public static Object newProxyInstance(ClassLoader loader,
>                                           Class<?>[] interfaces,
>                                           InvocationHandler h) {
