do {
	result += i;
	i += 1;
} while (i < 2);

System.out.println(result);  // 1

// 무조건 한번 실행되기 때문에, do 블록 내부의 실행문이 한번 실행 후 while 조건을 판별하여 반복 여부 결정
```

