### 1.  Response Time Interceptor

![](/notion/assets/2a011001e4185ae6.png)

<details>
<summary>**\[ 코드 \] ResponseTimeInterceptor**</summary>

<a id="27deda9b0fe181cfb942d23a01142b9e"></a>

```typescript
@Injectable()
export class ResponseTimeInterceptor implements NestInterceptor {
		intercept(context: ExecutionContext, next: CallHandler<ant>): Observable<any> | Promise<Observable<any>> {
				// Request Interceptor
				const req = context.switchToHttp().getRequest();

				const reqTime = Date.now();

				// Response Interceptor
				return next.handle()
						.pipe(
								const resTime = Date.now();
								const diff = resTime - reqTime;

								console.log(`[${req.method} ${req.path}] ${diff}ms`);
						)
		}
}
```

