<a id="28beda9b0fe180f8845dc9dbd1d7d4b8"></a>

### 테이블 생성

> ✏️ 
> 
> - `up()`: 마이그레이션을 **<u>진행</u>**할 때, 실행하는 메서드
> 
> - `down()`: 마이그레이션을 **<u>롤백</u>**할 때, 실행하는 메서드

<details>
<summary>**RAW SQL**</summary>

![](/notion/assets/b53f60dc5b5450ba.png)

<details>
<summary>\[ 코드 \] Raw SQL</summary>

<a id="28beda9b0fe18018bd48e29ebdb8b613"></a>

```typescript
import { MigrationInterface, QueryRunner } from "typeorm";

export class CreateMovieAndDirectorTables1634567890123 implements MigrationInterface {
		public async up(queryRunner: QueryRunner): Promise<void> {
				await queryRunner.query(`
						CREATE TABLE "director" (
								"id" SERIAL NOT NULL,
								"name" VARCHAR NOT NULL,
								"dob" DATE,
								"nationality" VARCHAR,
								PRIMARY KET ("id")
						)
				`);

				await queryRunner.query(`
						CREATE TABLE "movie" (
								"id" SERIAL NOT NULL,
								"title" VARCHAR NOT NULL,
								"genre" VARCHAR,
								"directorId" INTEGER,
								PRIMARY KET ("id")
								FOREIGN KEY ("directorId") REFERENCES "director"("id") ON DELETE SET NULL
						)
				`);
		}

		public async down(queryRunner: QueryRunner): Promise<void> {
				await queryRunner.query(`DROP TABLE "movie"`);
				await queryRunner.query(`DROP TABLE "director"`);				
		}
}
```

</details>

</details>

<details>
<summary>**Migration API**</summary>

![](/notion/assets/85ecbbe4c5c4f6b0.png)

<details>
<summary>\[ 코드 \] **Migration API**</summary>

<a id="28beda9b0fe18050b602ed2fc5281123"></a>

```typescript
import { MigrationInterface, QueryRunner } from "typeorm";

export class CreateMovieAndDirectorTables1634567890123 implements MigrationInterface {
		public async up(queryRunner: QueryRunner): Promise<void> {
				await queryRunner.createTable(new Table({
						name: "movie",
						columns: [
								{
										name: "id",
										type: "int",
										isPrimary: true,
										isGenerated: true,
										generationStrategy: "increment"
								},
								{
										name: "title",
										type: "varcher",
								},
								{
										name: "genre",
										type: "varchar",
										isNullable: true
								},
								{
										name: "directorid",
										type: "int",
										isNullable: true
								}
						]
				}), true);

				await queryRunner.createForeignKey("movie", new TableForeignKey({
						columnNames: ["directorId"],
						referencedColumnNames: ["id"],
						referencedTableName: "director",
						onDelete: "SET NULL"
				}));
		}

		public async down(queryRunner: QueryRunner): Promise<void> {
				await queryRunner.dropTable("movie");
				await queryRunner.dropTable("director");				
		}
}
```

</details>

</details>

