### 2. MongoDB 연결

> ✏️ 
> 
> - DB 연결: [페이지](../%EA%B8%B0%EB%B3%B8%20%EC%84%B8%ED%8C%85-%20Nest%20%ED%94%84%EB%A1%9C%EC%A0%9D%ED%8A%B8%20%EB%B0%8F%20%20MongoDB%20%EC%84%A4%EC%A0%95-ef853ac5fbf0/index.md) 
> 
> - 환경변수 설정: [페이지](../%ED%99%98%EA%B2%BD%EB%B3%80%EC%88%98%20%28config%29%20%EC%84%A4%EC%A0%95-faeeff88659d/index.md) 

<a id="22eeda9b0fe1809a9584e33b0e47f2c0"></a>

```typescript
import { Module } from '@nestjs/common';
import { AppController } from './app.controller';
import { AppService } from './app.service';
import { MongooseModule } from '@nestjs/mongoose';
import { ConfigModule } from '@nestjs/config';

@Module({
  imports: [
		ConfigModule.forRoot({ isGlobal: true }),  // .env import 설정
    MongooseModule.forRoot(  // MongoDB connect 설정
      process.env.MONGODB_URI || 'mongodb://localhost/nest',
      {
        dbName: 'nest',
      },
    ),
  ],
  controllers: [AppController],
  providers: [AppService],
})
export class AppModule implements NestModule {
  private readonly isDev: boolean = process.env.MODE === 'dev' ? true : false;
  configure(consumer: MiddlewareConsumer) {
    consumer.apply(LoggerMiddleware).forRoutes('*');  // 로깅 미들웨어 설정
    mongoose.set('debug', this.isDev); // Mongoose 디버그 모드 활성화
  }
}
```

