@Entity()
export class User {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  name: string;
}
```

</details>

<details>
<summary>\[ 코드 \] UserModule - `TypeOrmModule.forFeature(...)`로 엔티티 등록</summary>

<a id="234eda9b0fe180e6a208c2e5470d6785"></a>

```typescript
import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { User } from './user.entity';

@Module({
  imports: [TypeOrmModule.forFeature([User])], // 각 모듈마다 forFeature()를 통해 자동으로 불러옴
})
export class UserModule {}
```

</details>

<details>
<summary>\[ 코드 \] Product</summary>

<a id="234eda9b0fe1804da9b8e4f1a6bff9fc"></a>

```typescript
import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

@Entity()
export class Product {
  @PrimaryGeneratedColumn()
  id: number;

  @Column()
  title: string;
}
```

</details>

<details>
<summary>\[ 코드 \] ProductModule - `TypeOrmModule.forFeature(...)`로 엔티티 등록</summary>

<a id="234eda9b0fe1805dbfe6fe983eb5d5e6"></a>

```typescript
import { Module } from '@nestjs/common';
import { TypeOrmModule } from '@nestjs/typeorm';
import { Product } from './product.entity';

@Module({
  imports: [TypeOrmModule.forFeature([Product])], // 👈 마찬가지로 자동 등록됨
