## 리스트 ( List )

---

> ✏️ 
> 
> <a id="1cbeda9b0fe180449041d6244bac3175"></a>
> 
> **List**
> 
> ---
> 
> <a id="1cbeda9b0fe1805c9b58cec2f20d9b01"></a>
> 
> **<u>순서가 있고, 중복을 허용</u>**하는 자료구조를 리스트(**`List`**)라 한다. 
> 
> <a id="1cbeda9b0fe180d2842ee6cc682b9def"></a>
> 
> 이전에 직접 구현한 **`MyArrayList`** 와 **`MyLinkedList`**는 내부 **<u>구현만 다를 뿐</u>**<u> </u>**<u>같은 기능을 제공하는 리스트</u>**이다. 
> 
> <a id="1cbeda9b0fe180af9787e90a4a66184f"></a>
> 
> 내부 구현이 다르기 때문에 상황에 따라 성능이 달라질 수 있으나, **<u>사용자 입장에서 보면 같은 기능을 제공</u>**한다. ( 동일 형태의 메서드 구조 )
> 
> <a id="1cbeda9b0fe180d6bb7de61a3a6720a8"></a>
> 
> 따라서**<u> 이 둘의 공통 기능을 인터페이스로 뽑아 추상화</u>**하고 **<u>다형성을 활용</u>**한다면 여러 이점을 얻을 수 있따.

<a id="1cbeda9b0fe180a39c78c65730e28084"></a>

### 추상화 1 - 인터페이스 도입

![](/notion/assets/e89f53d422f10908.png)

<a id="1cbeda9b0fe180a4a95cc6e8226abc71"></a>

### 코드

<details>
<summary>\[ 코드 \] &lt; interface &gt; MyList</summary>

<a id="1cbeda9b0fe180fe9458d4e5cc29a8cb"></a>

```java
package collection.list;

public interface MyList<E> {

    int size();

    void add(E e);

    void add(int index, E e);

    E get(int index);

    E set(int index, E elemenet);

    E remove(int index);

    int indexOf(E o);
}

```

</details>

<details>
<summary>\[ 코드 \] MyArrayList</summary>

<a id="1cbeda9b0fe180579c7ed1ff92e70c78"></a>

```java
package collection.list;

import java.util.Arrays;

public class MyArrayList<E> implements MyList<E> {

    private static final int DEFAULT_CAPACITY = 5;

    // 왜 제네릭을 사용하지 않고 Object를 사용하는가? E로 선언 시, new E[]로 Array 를 생성해야 한다.
    private Object[] elementData;
    private int size = 0;

    public MyArrayList(Object[] elementData) {
        this.elementData = new Object[DEFAULT_CAPACITY];  // new E[] 는 타입 이레이저로 인해 타입 오류가 발생된다.
    }

    public MyArrayList(int initialCapacity) {
        elementData = new Object[initialCapacity];
    }

    @Override
    public int size() {
        return size;
    }

    @Override
    public void add(E e) {
        if (size == elementData.length) {
            grow();
        }
        elementData[size] = e;
        size++;
    }

    @Override
    public void add(int index, E e) {
        if (size == elementData.length) {
            grow();
        }
        shiftRightFrom(index);
        elementData[index] = e;
        size++;
    }

    // 요소 index 부터 마지막까지 왼쪽으로 밀기
    private void shiftRightFrom(int index) {
        for (int i = size; i > index; i--) {
            elementData[i] = elementData[i - 1];
        }
    }

    @Override
    @SuppressWarnings("unchecked")
    public E get(int index) {
        return (E) elementData[index];
    }

    @Override
    @SuppressWarnings("unchecked")
    public E set(int index, E element) {
        elementData[index] = element;
        return (E) elementData[index];
    }

    @Override
    public E remove(int index) {
        E oldValue = get(index);
        shiftLeftFrom(index);

        size--;
        elementData[size] = null;
        return oldValue;
    }

    private void shiftLeftFrom(int index) {
        for (int i = index; i < size; i++) {
            elementData[i] = elementData[i + 1];
        }
    }

    @Override
    public int indexOf(E o) {
        for (int i = 0; i < size; i++) {
            if (o.equals(elementData[i])) {
                return i;
            }
        }
        return -1;
    }

    private void grow() {
        int oldCapacity = size;
        int newCapacity = oldCapacity * 2;
        elementData = Arrays.copyOf(elementData, newCapacity);
    }

    @Override
    public String toString() {
        return Arrays.toString(Arrays.copyOf(elementData, size)) + " size=" + size  + ", capacity=" + elementData.length;
    }
}

```

</details>

<details>
<summary>\[ 코드 \] MyLinkedList</summary>

<a id="1cbeda9b0fe18028b84fca6f9a949809"></a>

```java
package collection.list;

public class MyLinkedList<E> implements MyList<E> {
    private Node<E> first;
    private int size = 0;

    @Override
    public void add(E e) {
        Node<E> newNode = new Node<>(e);
        if (first == null) {
            first = newNode;
        } else {
            Node<E> lastNode = getLastNode();
            lastNode.next = newNode;
        }
        size++;
    }

    private Node<E> getLastNode() {
        if(first ==  null) return first;
        Node<E> x = first;
        while (x.next != null) {
            x = x.next;
        }
        return x;
    }

    @Override
    public void add(int index, E e) {
        Node<E> newNode = new Node<E>(e);
        if (index == 0) {
            newNode.next = first;
            first = newNode;
        } else {
            Node<E> prev = getNode(index - 1);
            newNode.next = prev.next;
            prev.next = newNode;
        }
        size++;
    }

    @Override
    public E set(int index, E elemenet) {
        Node<E> x = getNode(index);
        E oldValue = x.item;
        x.item = elemenet;
        return oldValue;
    }

    @Override
    public E remove(int index) {
        Node<E> removeNode = getNode(index);
        E removeValue = removeNode.item;
        if (index == 0) {
            first = removeNode.next;
        } else {
            Node<E> prev = getNode(index - 1);
            prev.next = removeNode.next;
        }
        removeNode.item = null;
        removeNode.next = null;
        size--;
        return removeValue;
    }

    @Override
    public E get(int index) {
        Node<E> node = getNode(index);
        return node.item;
    }

    private Node<E> getNode(int index) {
        Node<E> x = first;
        for (int i = 0; i < index; i++) {
            x = x.next;
        }
        return x;
    }

    @Override
    public int indexOf(E o) {
        int index = 0;
        for (Node<E> x = first; x != null; x = x.next) {
            if (o.equals(x.item)) {
                return index;
            }
            index++;
        }
        return -1;
    }

    @Override
    public int size() {
        return size;
    }

    @Override
    public String toString() {
        return "MyLinkedList{" +
                "first=" + first +
                ", size=" + size +
                '}';
    }

    private static class Node<E> {
        E item;
        Node<E> next;

        public Node(E item) {
            this.item = item;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder();
            Node<E> temp = this;
            sb.append("[");
            while (temp != null) {
                sb.append(temp.item);
                if (temp.next != null) {
                    sb.append("->");
                }
                temp = temp.next;
            }
            sb.append("]");
            return sb.toString();
        }
    }
}

```

</details>

