// 실제 글을 작성하는 객체
public class TextEditor {
    private String text = "";

    public void write(String newText) {
        this.text += newText;
    }

    public String getText() {
        return text;
    }

    // 현재 상태 저장
    public TextMemento save() {
        return new TextMemento(text);
    }

    // 저장된 상태 복원
    public void restore(TextMemento memento) {
        this.text = memento.getText();
    }
