        - **JwtAuthorizationFilter** : API에 전달되는 JWT 유효성 검증 및 인가 처리
            <details>
            <summary>\[코드 스니펫\] **JwtAuthorizationFilter**</summary>

            <a id="1c3eda9b0fe18160886dc0036490f706"></a>

            ```java
            package com.sparta.myselectshop.security;

            import com.sparta.myselectshop.jwt.JwtUtil;
            import io.jsonwebtoken.Claims;
            import jakarta.servlet.FilterChain;
            import jakarta.servlet.ServletException;
            import jakarta.servlet.http.HttpServletRequest;
            import jakarta.servlet.http.HttpServletResponse;
            import lombok.extern.slf4j.Slf4j;
            import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
            import org.springframework.security.core.Authentication;
            import org.springframework.security.core.context.SecurityContext;
            import org.springframework.security.core.context.SecurityContextHolder;
            import org.springframework.security.core.userdetails.UserDetails;
            import org.springframework.util.StringUtils;
            import org.springframework.web.filter.OncePerRequestFilter;

            import java.io.IOException;

            @Slf4j(topic = "JWT 검증 및 인가")
            public class JwtAuthorizationFilter extends OncePerRequestFilter {

                private final JwtUtil jwtUtil;
                private final UserDetailsServiceImpl userDetailsService;

                public JwtAuthorizationFilter(JwtUtil jwtUtil, UserDetailsServiceImpl userDetailsService) {
                    this.jwtUtil = jwtUtil;
                    this.userDetailsService = userDetailsService;
                }

                @Override
                protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain filterChain) throws ServletException, IOException {

                    String tokenValue = jwtUtil.getJwtFromHeader(req);

                    if (StringUtils.hasText(tokenValue)) {

                        if (!jwtUtil.validateToken(tokenValue)) {
                            log.error("Token Error");
                            return;
                        }

                        Claims info = jwtUtil.getUserInfoFromToken(tokenValue);

                        try {
                            setAuthentication(info.getSubject());
                        } catch (Exception e) {
                            log.error(e.getMessage());
                            return;
                        }
                    }

                    filterChain.doFilter(req, res);
                }

                // 인증 처리
                public void setAuthentication(String username) {
                    SecurityContext context = SecurityContextHolder.createEmptyContext();
                    Authentication authentication = createAuthentication(username);
                    context.setAuthentication(authentication);

                    SecurityContextHolder.setContext(context);
                }

                // 인증 객체 생성
                private Authentication createAuthentication(String username) {
                    UserDetails userDetails = userDetailsService.loadUserByUsername(username);
                    return new UsernamePasswordAuthenticationToken(userDetails, null, userDetails.getAuthorities());
                }
            }
            ```

            </details>

        - 'Spring Security' 설정 및 인증/인가 필터 등록
            <details>
            <summary>**\[코드 스니펫\] WebSecurityConfig**</summary>

            <a id="1c3eda9b0fe181be9381c2d56ee56311"></a>

            ```java
            package com.sparta.myselectshop.config;


            import com.sparta.myselectshop.jwt.JwtUtil;
            import com.sparta.myselectshop.security.JwtAuthenticationFilter;
            import com.sparta.myselectshop.security.JwtAuthorizationFilter;
            import com.sparta.myselectshop.security.UserDetailsServiceImpl;
            import lombok.RequiredArgsConstructor;
            import org.springframework.boot.autoconfigure.security.servlet.PathRequest;
            import org.springframework.context.annotation.Bean;
            import org.springframework.context.annotation.Configuration;
            import org.springframework.security.authentication.AuthenticationManager;
            import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
            import org.springframework.security.config.annotation.web.builders.HttpSecurity;
            import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
            import org.springframework.security.config.http.SessionCreationPolicy;
            import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
            import org.springframework.security.crypto.password.PasswordEncoder;
            import org.springframework.security.web.SecurityFilterChain;
            import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;

            @Configuration
            @EnableWebSecurity // Spring Security 지원을 가능하게 함
            @RequiredArgsConstructor
            public class WebSecurityConfig {

                private final JwtUtil jwtUtil;
                private final UserDetailsServiceImpl userDetailsService;
                private final AuthenticationConfiguration authenticationConfiguration;

                @Bean
                public PasswordEncoder passwordEncoder() {
                    return new BCryptPasswordEncoder();
                }

                @Bean
                public AuthenticationManager authenticationManager(AuthenticationConfiguration configuration) throws Exception {
                    return configuration.getAuthenticationManager();
                }

                @Bean
                public JwtAuthenticationFilter jwtAuthenticationFilter() throws Exception {
                    JwtAuthenticationFilter filter = new JwtAuthenticationFilter(jwtUtil);
                    filter.setAuthenticationManager(authenticationManager(authenticationConfiguration));
                    return filter;
                }

                @Bean
                public JwtAuthorizationFilter jwtAuthorizationFilter() {
                    return new JwtAuthorizationFilter(jwtUtil, userDetailsService);
                }

                @Bean
                public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
                    // CSRF 설정
                    http.csrf((csrf) -> csrf.disable());

                    // 기본 설정인 Session 방식은 사용하지 않고 JWT 방식을 사용하기 위한 설정
                    http.sessionManagement((sessionManagement) ->
                            sessionManagement.sessionCreationPolicy(SessionCreationPolicy.STATELESS)
                    );

                    http.authorizeHttpRequests((authorizeHttpRequests) ->
                            authorizeHttpRequests
                                    .requestMatchers(PathRequest.toStaticResources().atCommonLocations()).permitAll() // resources 접근 허용 설정
                                    .requestMatchers("/").permitAll() // 메인 페이지 요청 허가
                                    .requestMatchers("/api/user/**").permitAll() // '/api/user/'로 시작하는 요청 모두 접근 허가
                                    .anyRequest().authenticated() // 그 외 모든 요청 인증처리
                    );

                    http.formLogin((formLogin) ->
                            formLogin
                                    .loginPage("/api/user/login-page").permitAll()
                    );

                    // 필터 관리
                    http.addFilterBefore(jwtAuthorizationFilter(), JwtAuthenticationFilter.class);
                    http.addFilterBefore(jwtAuthenticationFilter(), UsernamePasswordAuthenticationFilter.class);

                    return http.build();
                }
            }
            ```

