<a id="11ceda9b0fe180578d38d7a9dea30116"></a>

```java

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;


class Node {
    protected int val;
    protected Node next;

    Node(int val, Node next) {
        this.val = val;
        this.next = next;
    }

}

class LinkedList {
    private static Node head = null;

    // 생성
    public void add(int value) {
        // LinkedList 초기화
        if(head == null){
            head = new Node(value, null);
            return;
        }

        Node node = head;
        while(node.next != null){
            node = node.next;
        }

        node.next = new Node(value, null);
    }

    // 조회
    public int get(int index){
        if(head == null){
            System.out.println("조회할 노드개 존재하지 않습니다.");
            return -1;
        }

        Node node = head;
        while(index>0){
            node = node.next;
            index--;
        }


        return node.val;
    }


    // 수정
    public void update(int index, int value){
        if(index < 0) {
            System.out.println("index는 0이상부터 가능합니다.");
            return;
        }

        int prtIdx = index;

        Node node = head;

        while(index>0){
            if(node.next==null){
                System.out.println("해당하는 index = " + prtIdx + " 의 노드는 존재하지 않습니다.");
                return;
            }
            node = node.next;
            index--;
        }
        node.val=value;

        System.out.println(prtIdx + "번째 node 값이 " + value +"로 수정 됐습니다.");
    }

    // 제거
    public int remove(){
        if(head==null){
            System.out.println("삭제할 노드가 존재하지 않습니다.");
            return -1;
        }
        Node node = head;

        head = node.next;
        return node.val;
    }
}
public class Main {
    public static void main(String[] args) {
        LinkedList list = new LinkedList();
        list.add(1);
        list.add(2);
        list.add(3);

        // 조회
        System.out.println(list.get(2));  // 3
        System.out.println(list.get(1));  // 2
        System.out.println(list.get(0));  // 1

        // 수정
        list.update(1, 5);
        System.out.println(list.get(1));  // 5

        // 삭제
        System.out.println(list.remove());  // 2
        System.out.println(list.remove());  // 3 , update
        System.out.println(list.remove());  // 0
        System.out.println(list.remove());  // -1

    }
}

```

